type Product={id:string;selected?:boolean;customerItem:string;model:string;en:string;zh:string;hs:string;brand:string;material:string;usage:string;capacity:string;color:string;qty:number;unit:string;price:number;freeQty:number;freeAmount:number;discount:number;pcsCtn:number;nw:number;gw:number;l:number;w:number;h:number;origin:string;declaration:string;mark:string;remark:string;cartonsOverride?:number;totalNwOverride?:number;totalGwOverride?:number;totalCbmOverride?:number};
type Party={name:string;address:string;country:string;contact:string;phone:string;email:string;tax:string};
type DocType="Commercial Invoice"|"Packing List"|"Proforma Invoice"|"Sales Contract"|"Customs Declaration Data"|"Booking Note"|"Certificate of Origin Data"|"Forwarder Handover Sheet";
type Shipment={version:number;id:string;demo?:boolean;createdAt:string;updatedAt:string;basic:Record<string,string>;seller:Party&{cn:string;bank:string;bankAddress:string;account:string;accountNo:string;swift:string};buyer:Party;consignee:Party;notify:Party;products:Product[];packingProducts?:Product[];transport:Record<string,string|boolean>;certificate:Record<string,string>;contract:string};

const SELLER={cn:"广州奥晨包装有限公司",name:"GUANGZHOU AC SKINCARE PACKAGING CO., LTD",address:"RM 1002, Shuixi Fuye 1st Street, Huangpu District, Guangzhou, China",country:"China",contact:"Anne",phone:"+86 186 8840 7515",email:"anne@skincarepkg.com",tax:"",bank:"",bankAddress:"",account:"GUANGZHOU AC SKINCARE PACKAGING CO., LTD",accountNo:"",swift:""};
const blankParty=():Party=>({name:"",address:"",country:"",contact:"",phone:"",email:"",tax:""});
const product=(x:Partial<Product>={}):Product=>({id:crypto.randomUUID(),customerItem:"",model:"",en:"",zh:"",hs:"",brand:"",material:"",usage:"",capacity:"",color:"",qty:0,unit:"PCS",price:0,freeQty:0,freeAmount:0,discount:0,pcsCtn:1,nw:0,gw:0,l:0,w:0,h:0,origin:"China",declaration:"",mark:"N/M",remark:"",...x});
