const blank=():Shipment=>{const d=today(),no=`AC-${d.replaceAll("-","")}-001`;return {version:1,id:crypto.randomUUID(),createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),basic:{shipment:"",orderNo:no,invoiceNo:no,packingNo:no,piNo:no,contractNo:no,poNo:"",invoiceDate:d,orderDate:d,shipDate:"",currency:"USD",incoterm:"FOB Guangzhou",payment:"T/T",origin:"China",remarks:""},seller:{...SELLER},buyer:blankParty(),consignee:blankParty(),notify:blankParty(),products:[product()],transport:{mode:"Sea",type:"FCL",loading:"Guangzhou",discharge:"",destination:"",line:"",vessel:"",voyage:"",etd:"",eta:"",forwarder:"",forwarderContact:"",forwarderEmail:"",forwarderPhone:"",booking:"",bl:"",container:"",seal:"",containerType:"40HQ",containerQty:"1",commodity:"Plastic packaging",dangerous:false,battery:false,wood:false,fumigation:false,customsMode:"General Trade",broker:"",brokerContact:"",customsCutoff:"",vgmCutoff:"",siCutoff:"",warehouse:"",warehouseNo:"",special:"",remarks:""},certificate:{type:"CO",originCriterion:"WO",manufacturer:SELLER.name,place:"Guangzhou",date:d,signatory:"Anne",remarks:""},contract:"Quality: Products shall conform to the confirmed samples.\nInspection: Buyer shall inspect goods upon receipt.\nClaims: Claims must be raised within 15 days of receipt.\nForce Majeure: Neither party is liable for events beyond reasonable control.\nArbitration: Disputes shall be settled by friendly negotiation or arbitration in Guangzhou."};};
const demo=():Shipment=>{const s=blank();s.demo=true;s.basic={...s.basic,shipment:"DEMO — Autumn Skincare Packaging",orderNo:"AC-20260807-001",invoiceNo:"AC2026001",packingNo:"PL2026001",piNo:"PI2026001",contractNo:"SC2026001",poNo:"ABC-PO-817",shipDate:"2026-08-20",remarks:"演示数据 / DEMO DATA"};s.buyer={name:"ABC Beauty Ltd.",address:"88 King Street, London",country:"United Kingdom",contact:"Emma Brown",phone:"+44 20 0000 0000",email:"emma@example.com",tax:"GB123456789"};s.consignee={...s.buyer};s.notify={...s.buyer};s.products=[product({customerItem:"JAR-050",model:"AC-J50",en:"50ml Cosmetic Cream Jar",zh:"50毫升面霜罐",hs:"3923300000",brand:"OEM",material:"PP",usage:"Cosmetic packaging",capacity:"50ml",color:"Ivory",qty:1200,price:0.82,freeQty:20,freeAmount:16.4,pcsCtn:100,nw:8.2,gw:9.1,l:48,w:38,h:32,declaration:"PP cosmetic jar; 50ml; non-electric",mark:"ABC / LONDON"}),product({customerItem:"BOT-100",model:"AC-B100",en:"100ml Airless Pump Bottle",zh:"100毫升真空泵瓶",hs:"3923300000",brand:"OEM",material:"PP",usage:"Cosmetic packaging",capacity:"100ml",color:"White",qty:600,price:1.28,pcsCtn:60,nw:7.5,gw:8.4,l:52,w:42,h:36,declaration:"PP airless bottle; 100ml; non-electric",mark:"ABC / LONDON"})];s.transport={...s.transport,discharge:"London Gateway",destination:"London",forwarder:"Global Freight Ltd.",booking:"BK-DEMO-001",etd:"2026-08-20",eta:"2026-09-18",warehouse:"Nansha Export Warehouse, Guangzhou",siCutoff:"2026-08-17T17:00"};return s};
const n=(v:unknown)=>typeof v==="number"?(Number.isFinite(v)?v:0):Number(String(v??"").replace(/,/g,"").replace(/[^0-9.-]/g,""))||0, money=(v:number)=>v.toFixed(2), round=(v:number,d=3)=>Number(v.toFixed(d));
const safe=(v:unknown)=>String(v??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]!));
const downloadBlob=(blob:Blob,name:string)=>{const url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)};
const calc=(p:Product)=>{const cartons=p.cartonsOverride??(n(p.pcsCtn)>0?Math.ceil(n(p.qty)/n(p.pcsCtn)):0),amount=round(n(p.qty)*n(p.price),2),cbm=round(n(p.l)*n(p.w)*n(p.h)/1e6,4);return {cartons,amount,final:round(amount-n(p.freeAmount)-n(p.discount),2),tnw:p.totalNwOverride??round(n(p.nw)*cartons),tgw:p.totalGwOverride??round(n(p.gw)*cartons),cbm,totalCbm:p.totalCbmOverride??round(cbm*cartons,4)}};
const DOCS:DocType[]=["Commercial Invoice","Packing List"];
const docLabel=(x:string)=>x==="Commercial Invoice"?"整套客户清关资料 · Commercial Invoice + Packing List":x==="Packing List"?"单独装箱清单 · Packing List":x;

const norm=(v:unknown)=>String(v??"").replace(/\s+/g," ").trim();
const key=(v:unknown)=>norm(v).toLowerCase().replace(/[\s._/\-()（）]+/g,"");
const aliases:Record<string,string[]>={model:["model","型号","suppliermodel"],en:["englishdescription","description","product","productionname","货名","品名"],zh:["chinesedescription","中文品名","产品名"],hs:["hscode","商品编码","海关编码"],qty:["quantity","qty","数量","订货数量"],unit:["unit","单位"],price:["unitprice","单价"],cartons:["cartons","carton","package","packages","箱数","总箱数","件数"],nw:["netweight","nw","净重"],gw:["grossweight","gw","毛重"],cbm:["cbm","measurement","体积"],mark:["marksno","marks","唛头"]};
const colFor=(row:unknown[],name:string)=>row.findIndex(v=>aliases[name].some(a=>key(v).includes(key(a))));
const lastColFor=(row:unknown[],name:string)=>{for(let i=row.length-1;i>=0;i--)if(aliases[name].some(a=>key(row[i]).includes(key(a))))return i;return-1};
const chineseName=(name:string)=>/\bbox\b|paper\s*box|carton/i.test(name)?"纸盒":/jar/i.test(name)?"面霜罐":/pump/i.test(name)?"塑料泵头":/cap|cover/i.test(name)?"塑料盖":/bottle/i.test(name)?"塑料瓶":"";
function readSourceWorkbook(buffer:ArrayBuffer,kind:"pi"|"packing"){
 const wb=XLSX.read(buffer,{type:"array",cellDates:true}), result:{basic:Record<string,string>;buyer:Partial<Party>;products:Partial<Product>[]}={basic:{},buyer:{},products:[]};
 for(const sheetName of wb.SheetNames){const ws=wb.Sheets[sheetName],rows=XLSX.utils.sheet_to_json<unknown[]>(ws,{header:1,defval:"",raw:false}),flat=rows.flat().map(norm).filter(Boolean);
  if(kind==="pi"&&/invoice|\bpi\b/i.test(sheetName)){const groups:number[]=[];rows.forEach((row,i)=>{if(key(row[3])==="product"&&norm(row[4]))groups.push(i)});if(groups.length){const getLabel=(from:number,to:number,re:RegExp)=>{for(let i=from;i<to;i++)if(re.test(norm(rows[i]?.[3])))return norm(rows[i]?.[4]);return ""};const products=groups.map((from,j)=>{const to=groups[j+1]??rows.length,name=norm(rows[from]?.[4]),qty=n(getLabel(from,to,/quantity/i)),price=n(getLabel(from,to,/total unit price|unit price|sample fee/i)),model=getLabel(from,to,/^model$/i),size=getLabel(from,to,/^size$/i),material=getLabel(from,to,/material/i);return {model,en:[name,size].filter(Boolean).join(" "),zh:chineseName(name),material,capacity:size,qty,unit:"PCS",price,pcsCtn:0,mark:"N/M"} as Partial<Product>}).filter(p=>n(p.qty)>0&&!!p.en);const cells=rows.flat().map(norm);const field=(re:RegExp)=>cells.find(v=>re.test(v))?.replace(re,"").trim()||"";result.basic.piNo=field(/^PI\s*NO\s*[:：]?/i);result.basic.invoiceNo=result.basic.piNo;result.basic.invoiceDate=field(/^Date\s*[:：]?/i).replace(/[/.]/g,"-");result.basic.currency="USD";result.buyer.name=field(/^Buyer\s*[:：]?/i);result.buyer.contact=field(/^Name\s*[:：]?/i);result.buyer.email=field(/^Tel\/Email\s*[:：]?/i);result.buyer.address=field(/^Address\s*[:：]?/i);result.products=products;return result}}
  const joined=flat.join("\n"),match=(re:RegExp)=>joined.match(re)?.[1]?.trim()||"";
  result.basic.invoiceNo ||= match(/(?:invoice\s*(?:no\.?|number)|发票号码?)\s*[:：]?\s*([^\n]+)/i);
  result.basic.piNo ||= match(/(?:pi\s*(?:no\.?)?|形式发票编号)\s*[:：]?\s*([^\n]+)/i);
  result.basic.contractNo ||= match(/(?:contract\s*(?:no\.?)?|合同号)\s*[:：]?\s*([^\n]+)/i);
  result.basic.invoiceDate ||= match(/(?:date|日期)\s*[:：]\s*(\d{4}[-/.]\d{1,2}[-/.]\d{1,2})/i).replace(/[/.]/g,"-");
  result.basic.currency ||= match(/(?:currency|币种)\s*[:：]?\s*([A-Z]{3})/i);
  result.basic.incoterm ||= match(/(?:incoterm|贸易条款)\s*[:：]?\s*([^\n]+)/i);
  const toIndex=flat.findIndex(v=>/^(to|messrs|buyer|consignee)\s*[:：]?/i.test(v));if(toIndex>=0){const first=flat[toIndex].replace(/^(to|messrs|buyer|consignee)\s*[:：]?\s*/i,"");result.buyer.name ||= first||flat[toIndex+1]||"";result.buyer.address ||= flat.slice(toIndex+1,toIndex+4).join(", ")}
  const headerIndex=rows.findIndex(row=>colFor(row,"en")>=0&&colFor(row,"qty")>=0);if(headerIndex<0)continue;const header=rows[headerIndex],idx=Object.fromEntries(Object.keys(aliases).map(k=>[k,colFor(header,k)]));if(kind==="packing")for(const k of ["cartons","nw","gw","cbm"])idx[k]=lastColFor(header,k);const body=rows.slice(headerIndex+1),totalAt=body.findIndex(row=>/^total$/i.test(norm(row[idx.en]))),validRows=totalAt>=0?body.slice(0,totalAt):body;
  for(const row of validRows){const get=(k:string)=>idx[k]>=0?row[idx[k]]:"",desc=norm(get("en")),qty=n(get("qty"));if(!desc||/^(total|subtotal|g\.total)/i.test(desc)||(!qty&&kind==="pi"))continue;const cartons=n(get("cartons")),p:Partial<Product>={model:norm(get("model")),en:desc,zh:norm(get("zh"))||chineseName(desc),hs:norm(get("hs")),qty,unit:norm(get("unit"))||"PCS",price:n(get("price")),mark:norm(get("mark"))||"N/M"};if(cartons>0&&qty>0)p.pcsCtn=Math.max(1,Math.round(qty/cartons));if(kind==="packing"){p.cartonsOverride=cartons;p.totalNwOverride=n(get("nw"));p.totalGwOverride=n(get("gw"));p.totalCbmOverride=n(get("cbm"));p.l=n(row[3]);p.w=n(row[4]);p.h=n(row[5]);p.nw=n(row[7]);p.gw=n(row[8]);p.pcsCtn=n(row[2])}result.products.push(p)}
 }
 if(kind==="packing"&&result.products.length){const grouped=new Map<string,Partial<Product>>();for(const p of result.products){const k=key(p.en);const old=grouped.get(k);if(!old)grouped.set(k,{...p});else grouped.set(k,{...old,cartonsOverride:n(old.cartonsOverride)+n(p.cartonsOverride),totalNwOverride:n(old.totalNwOverride)+n(p.totalNwOverride),totalGwOverride:n(old.totalGwOverride)+n(p.totalGwOverride),totalCbmOverride:n(old.totalCbmOverride)+n(p.totalCbmOverride)})}result.products=[...grouped.values()]}
 return result;
}

function CustomsDocumentView({s,totals}:any){const fields=[["境内发货人",s.seller.cn||s.seller.name],["出境关别",s.transport.customsOffice],["出口日期",s.basic.shipDate],["申报日期",s.basic.invoiceDate],["备案号",s.basic.recordNo],["境外收货人",s.buyer.name],["运输方式",s.transport.mode||"海运"],["运输工具名称及航次号",[s.transport.vessel,s.transport.voyage].filter(Boolean).join(" / ")],["提运单号",s.transport.bl],["许可证号",s.transport.licenseNo],["生产销售单位",s.seller.cn||s.seller.name],["监管方式","一般贸易"],["征免性质","一般征税"],["合同协议号",s.basic.contractNo||s.basic.poNo],["贸易国（地区）",s.buyer.country],["运抵国（地区）",s.buyer.country],["指运港",s.transport.discharge],["离境口岸",s.transport.loading],["包装种类/件数",`纸箱 / ${totals.cartons}`],["毛重/净重",`${totals.gw} / ${totals.nw}`],["成交方式",String(s.basic.incoterm||"").split(" ")[0]],["运费",s.transport.freight],["保费",s.transport.insurance],["杂费",s.transport.otherCharges],["境内货源地",s.transport.domesticOrigin||"待人工确认"]];return <article className="customs-paper"><h1>中华人民共和国海关出口货物报关单</h1><div className="customs-top"><span>预录入编号：</span><span>海关编号：</span><span>页码/页数：1/1</span></div><div className="customs-fields">{fields.map(([k,v]:any)=><div key={k}><b>{k}</b><span>{String(v||"")}</span></div>)}</div><div className="customs-wide"><b>随附单证及编号</b><span>发票、装箱单、报关单、报关委托书、进港箱单；发票号：{s.basic.invoiceNo}</span></div><div className="customs-wide marks"><b>标记唛码及备注</b><span>{s.products.map((p:Product)=>p.mark).filter(Boolean).join(" / ")||"N/M"}</span></div><table><thead><tr>{["项号","商品编号","商品名称及规格型号","数量及单位","单价/总价/币制","原产国（地区）","最终目的国（地区）","境内货源地","征免","备注"].map(x=><th key={x}>{x}</th>)}</tr></thead><tbody>{s.products.map((p:Product,i:number)=>{const c=calc(p);return <tr key={p.id}><td>{i+1}</td><td>{p.hs}</td><td>{p.zh}<br/>{p.model}<br/><small>{p.declaration}</small></td><td>{p.qty} {p.unit}</td><td>{p.price} / {c.final} / {s.basic.currency}</td><td>{p.origin||s.basic.origin}</td><td>{s.buyer.country}</td><td>{s.transport.domesticOrigin||"待人工确认"}</td><td>照章征税</td><td>{p.remark}</td></tr>})}</tbody></table><div className="customs-wide declaration"><b>申报要素及其他说明</b><span>{s.products.map((p:Product)=>p.declaration).filter(Boolean).join("；")}</span></div><div className="customs-wide preference">无品牌，出口货物不能确定在最终目的国（地区）享受优惠关税</div><div className="customs-sign"><div>报关人员<br/>税之法律责任<br/>申报单位</div><div>报关人员证号</div><div>电话</div><div>兹申明对以上内容承担如实申报、依法纳税之法律责任<br/>申报单位（签章）</div><div>海关批注及签章</div></div></article>}

function CertificateDocumentView({s}:any){const marks=s.products.map((p:Product)=>p.mark).filter(Boolean).join(" / ")||"N/M",descriptions=s.products.map((p:Product)=>`${p.en||p.zh} (${calc(p).cartons} CTNS)`).join("\n"),hs=[...new Set(s.products.map((p:Product)=>p.hs).filter(Boolean))].join(" / "),qty=s.products.map((p:Product)=>`${p.qty} ${p.unit}`).join("\n");return <article className="certificate-paper"><div className="cert-grid cert-top"><section><b>1. Exporter <em>发货人</em></b><p>{s.seller.name}<br/>{s.seller.address}<br/>{s.seller.phone} {s.seller.email}</p></section><section className="cert-title"><b>Certificate no.:</b><h1>CERTIFICATE OF ORIGIN<br/>OF<br/>THE PEOPLE&apos;S REPUBLIC OF CHINA</h1></section><section><b>2. Consignee <em>收货人</em></b><p>{s.consignee.name||s.buyer.name}<br/>{s.consignee.address||s.buyer.address}<br/>{s.consignee.country||s.buyer.country}</p></section><section className="cert-authority"><b>5. For certifying authority use only</b></section><section><b>3. Means of transport and route <em>运输路线</em></b><p>{s.transport.loading||""}, CHINA → {s.transport.discharge||""}<br/>{s.transport.mode||""}</p></section><section><b>4. Country/region of destination <em>目的地</em></b><p>{s.buyer.country||""}</p></section></div><div className="cert-goods"><section><b>6. Marks and number<br/><em>唛头</em></b><p>{marks}</p></section><section><b>7. Number and kind of packages/description of goods<br/><em>品名及箱数</em></b><p>{descriptions}</p></section><section><b>8. H.S.Code</b><p>{hs}</p></section><section><b>9. Quantity<br/><em>数量</em></b><p>{qty}</p></section><section><b>10. Number and date of invoices<br/><em>发票号及日期</em></b><p>{s.basic.invoiceNo}<br/>{s.basic.invoiceDate}</p></section></div><div className="cert-bottom"><section><b>11. Declaration by the exporter</b><p>Place: {s.certificate.place||"Guangzhou"}<br/>Date: {s.certificate.date||s.basic.invoiceDate}</p></section><section><b>12. Certification</b></section></div></article>}

function BookingDocumentView({s,totals}:any){const terms="1. 托运人请按运输惯例及有关责任要求正确填写托运单位；\n2. 因填写错误或资料不全引起的货损、延误由托运人承担；\n3. 运费与附加费按双方协定金额结算；\n4. 托运人应按付款时间结清全部运费；\n5. 货名及重量必须填报清楚并符合运输条款；\n6. 托运人必须由经办人签名并盖公司有效印章。";return <article className="booking-paper"><div className="booking-head"><section><b>SHIPPER（发货人）</b><p>{s.seller.name}<br/>{s.seller.cn}<br/>{s.seller.address}<br/>Email: {s.seller.email}<br/>Tel: {s.seller.phone}</p></section><section><b>BOOKING NO.（托运单号）</b><p>{s.transport.booking}</p></section><section><b>CONSIGNEE（收货人）</b><p>{s.consignee.name||s.buyer.name}<br/>{s.consignee.contact||s.buyer.contact}<br/>{s.consignee.address||s.buyer.address}<br/>{s.consignee.phone||s.buyer.phone}</p></section><section className="booking-title"><h1>BOOKING NOTE</h1><b>TEL: {s.transport.forwarderPhone}　FAX: {s.transport.fax}　CTC: {s.transport.forwarderContact}</b></section><section><b>NOTIFY PARTY（通知人）</b><p>{s.notify.name||"SAME AS CONSIGNEE"}<br/>{s.notify.address}</p></section><section><p>CY/CY（　）　CFS/CFS（　）　OTHERS（　）<br/>B/L NO# {s.transport.bl}　 JOB NO# {s.transport.warehouseNo}<br/>20′ ___　40′ ___　40′HQ ___　45′ ___　RR（ ）<br/>CBM {totals.cbm}　毛重 {totals.gw} KGS<br/>装货日期：{s.basic.shipDate||s.transport.etd}<br/>装货地点：{s.transport.warehouse}</p></section></div><div className="booking-charge"><section><b>FREIGHT &amp; CHARGE：____（ ）PREPAID 预付</b><p>（运费及附加费）　HKD ______（ ）COLLECT 到付<br/>投保金额：________　发票号：{s.basic.invoiceNo}<br/>投保类别：________　付款期限：{s.basic.payment}</p></section><section><b>SPECIAL REQUIREMENTS / 特别要求</b><p>{s.transport.special}</p></section></div><div className="booking-route">{[["OCEAN VES/VOY#（船名航次）",`${s.transport.vessel||""} ${s.transport.voyage||""}`],["PORT OF LOADING（装货港）",s.transport.loading],["PORT OF DISCHARGE（卸货港）",s.transport.discharge],["PLACE OF DELIVERY（目的港）",s.transport.destination]].map(([k,v]:any)=><section key={k}><b>{k}</b><p>{v}</p></section>)}</div><table><thead><tr><th>MARKS &amp; NO.<br/>箱唛标记及号码</th><th>NUMBER AND KIND OF PACKAGES &amp; DESCRIPTION OF GOODS<br/>件数及包装种类与货名</th><th>GROSS WEIGHT (KGS)<br/>毛重（公斤）</th><th>MEASR. (CBM)<br/>尺码（立方数）</th></tr></thead><tbody>{s.products.map((p:Product)=><tr key={p.id}><td>{p.mark}</td><td>{p.en}<br/>{p.zh}</td><td>{calc(p).tgw} KGS</td><td>{calc(p).totalCbm} CBM</td></tr>)}</tbody></table><div className="booking-bottom"><section><b>托运条款：</b><p>{terms}</p></section><section><p>运费支付人：{s.transport.forwarder}<br/><br/>托运人：{s.seller.contact}<br/><br/>日期：{s.basic.shipDate}</p></section></div></article>}
const labels:Record<string,[string,string]>={shipment:["出货项目名称","Shipment Name"],orderNo:["内部订单编号","Internal Order No."],invoiceNo:["商业发票编号","Invoice No."],packingNo:["装箱单编号","Packing List No."],piNo:["形式发票编号","PI No."],contractNo:["合同编号","Contract No."],poNo:["客户采购单号","Customer PO No."],invoiceDate:["发票日期","Invoice Date"],orderDate:["订单日期","Order Date"],shipDate:["预计出货日期","Estimated Shipping Date"],currency:["币种","Currency"],incoterm:["贸易条款","Incoterm"],payment:["付款方式","Payment Terms"],origin:["原产国","Country of Origin"],remarks:["备注","Remarks"]};

function Field({label,value,onChange,type="text",list}:{label:string;value:string|number;onChange:(v:string)=>void;type?:string;list?:string}){return <label className="field"><span>{label}</span><input type={type} list={list} value={value} onChange={e=>onChange(e.target.value)}/></label>}
function PartyForm({title,p,set}:{title:string;p:Party;set:(p:Party)=>void}){return <section className="subcard"><h3>{title}</h3><div className="form-grid"><Field label="Company Name 公司名称" value={p.name} onChange={v=>set({...p,name:v})}/><Field label="Country 国家" value={p.country} onChange={v=>set({...p,country:v})}/><Field label="Address 地址" value={p.address} onChange={v=>set({...p,address:v})}/><Field label="Contact 联系人" value={p.contact} onChange={v=>set({...p,contact:v})}/><Field label="Phone 电话" value={p.phone} onChange={v=>set({...p,phone:v})}/><Field label="Email 邮箱" value={p.email} onChange={v=>set({...p,email:v})}/><Field label="VAT / Tax ID" value={p.tax} onChange={v=>set({...p,tax:v})}/></div></section>}

async function exportTemplateWorkbook(s:Shipment,type:DocType,totals:{qty:number;cartons:number;amount:number;free:number;final:number;nw:number;gw:number;cbm:number},filename:string){
 const buffer=await fetch("/templates/ac-pkg-clearance-template.xlsx").then(r=>{if(!r.ok)throw new Error("template");return r.arrayBuffer()});
 const wb=XLSX.read(buffer,{type:"array",cellStyles:true,cellFormula:true,cellNF:true});
 const cell=(ws:XLSX.WorkSheet,address:string,value:string|number,formula?:string)=>{const old=ws[address]||{};ws[address]={...old,v:value,t:typeof value==="number"?"n":"s"};if(formula)ws[address].f=formula;else delete ws[address].f};
 const party=[s.buyer.name,s.buyer.address,[s.buyer.country,s.buyer.contact,s.buyer.email,s.buyer.phone].filter(Boolean).join("\n")].filter(Boolean).join("\n\n");
 const meta=`Invoice No:${s.basic.invoiceNo}\nPayment Terms: ${s.basic.payment}\nCountry of origin - ${s.basic.origin}\nDATE: ${s.basic.invoiceDate}`;
 const keep=type==="Packing List"?"Packing list":type==="Sales Contract"?"Contract":"Invoice";
 const ws=wb.Sheets[keep];
 if(keep==="Invoice"){
  cell(ws,"A1",s.seller.name);cell(ws,"A2",`${s.seller.address}\nPhone: ${s.seller.phone} Email: ${s.seller.email}`);cell(ws,"A4",type.toUpperCase());cell(ws,"B5",party);cell(ws,"G5",meta);cell(ws,"A8",s.products.map(p=>p.mark).filter(Boolean).join(" / ")||"N/M");
  s.products.slice(0,2).forEach((p,i)=>{const r=8+i,c=calc(p);cell(ws,`D${r}`,`${p.en}\n${p.zh}\nHS code: ${p.hs}`);cell(ws,`E${r}`,p.qty);cell(ws,`F${r}`,c.cartons);cell(ws,`G${r}`,p.price);cell(ws,`H${r}`,c.amount,`G${r}*E${r}`)});
  cell(ws,"D10","TOTAL");cell(ws,"H10",totals.amount,"SUM(H8:H9)");cell(ws,"D11","FREE OF CHARGE AMOUNT");cell(ws,"H11",totals.free);cell(ws,"D12","SUBTOTAL AMOUNT");cell(ws,"H12",totals.final,"H10-H11");
 }else if(keep==="Packing list"){
  cell(ws,"A1",s.seller.name);cell(ws,"A2",`${s.seller.address}\nPhone: ${s.seller.phone} Email: ${s.seller.email}`);cell(ws,"B4",party);cell(ws,"J4",`Invoice No:${s.basic.invoiceNo}\nCountry of origin - ${s.basic.origin}\nDATE: ${s.basic.invoiceDate}`);
  s.products.slice(0,2).forEach((p,i)=>{const r=9+i,c=calc(p);cell(ws,`A${r}`,i+1);cell(ws,`B${r}`,`${p.en}\n${p.zh}\nHS code: ${p.hs}`);cell(ws,`C${r}`,p.qty);cell(ws,`D${r}`,p.pcsCtn);cell(ws,`E${r}`,p.l);cell(ws,`F${r}`,p.w);cell(ws,`G${r}`,p.h);cell(ws,`H${r}`,c.cbm);cell(ws,`I${r}`,p.nw);cell(ws,`J${r}`,p.gw);cell(ws,`K${r}`,c.cartons);cell(ws,`L${r}`,c.tnw);cell(ws,`M${r}`,c.tgw);cell(ws,`N${r}`,c.totalCbm)});
  cell(ws,"A11","TOTAL");cell(ws,"K11",totals.cartons,"SUM(K9:K10)");cell(ws,"L11",totals.nw,"SUM(L9:L10)");cell(ws,"M11",totals.gw,"SUM(M9:M10)");cell(ws,"N11",totals.cbm,"SUM(N9:N10)");
 }else{
  cell(ws,"A1",s.seller.name);cell(ws,"A2",`${s.seller.address}\nPhone: ${s.seller.phone} Email: ${s.seller.email}`);cell(ws,"E5",s.basic.contractNo||s.basic.piNo);cell(ws,"E6",s.basic.orderDate);
  s.products.slice(0,6).forEach((p,i)=>{const r=9+i,c=calc(p);cell(ws,`A${r}`,`${p.en}\n${p.zh}\n${p.model}`);cell(ws,`B${r}`,p.qty);cell(ws,`C${r}`,p.unit);cell(ws,`D${r}`,p.price);cell(ws,`E${r}`,c.final)});cell(ws,"E15",totals.final,"SUM(E9:E14)");cell(ws,"A17",`Shipment: ${s.basic.shipDate}`);cell(ws,"A19",`Port of loading: ${String(s.transport.loading)}`);cell(ws,"C19",`Port of Destination: ${String(s.transport.discharge)}`);cell(ws,"A20",s.contract);
 }
 wb.SheetNames.filter(n=>n!==keep).forEach(n=>{delete wb.Sheets[n]});wb.SheetNames=[keep];
 const bytes=XLSX.write(wb,{type:"array",cellStyles:true,bookType:"xlsx"});const url=URL.createObjectURL(new Blob([bytes],{type:"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"}));const link=document.createElement("a");link.href=url;link.download=filename;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
}

export default function ShippingAssistant(){
 const [s,setS]=useState<Shipment>(blank);const [step,setStep]=useState(0);const [lang,setLang]=useState<"zh"|"en">("zh");const [doc,setDoc]=useState<DocType>(DOCS[0]);const [preview,setPreview]=useState(false);const [includeStamp,setIncludeStamp]=useState(false);const [toast,setToast]=useState("");const [history,setHistory]=useState<Shipment[]>([]);const [query,setQuery]=useState("");const [backupOpen,setBackupOpen]=useState(false);const [sourceFiles,setSourceFiles]=useState({pi:"",packing:""});const [confirm,setConfirm]=useState<{text:string;go:()=>void}|null>(null);const importRef=useRef<HTMLInputElement>(null);const productRef=useRef<HTMLInputElement>(null);const piRef=useRef<HTMLInputElement>(null);const packingRef=useRef<HTMLInputElement>(null);const hydrated=useRef(false);
 useEffect(()=>{try{const d=localStorage.getItem("acpkg.shipping.draft"),h=localStorage.getItem("acpkg.shipping.history");if(d)setS(JSON.parse(d));if(h)setHistory(JSON.parse(h));}catch{}hydrated.current=true},[]);
 useEffect(()=>{if(!hydrated.current)return;const t=setTimeout(()=>{localStorage.setItem("acpkg.shipping.draft",JSON.stringify({...s,updatedAt:new Date().toISOString()}))},500);return()=>clearTimeout(t)},[s]);
 const update=(fn:(x:Shipment)=>Shipment)=>setS(x=>fn({...x,updatedAt:new Date().toISOString()}));const say=(x:string)=>{setToast(x);setTimeout(()=>setToast(""),2400)};
 const totals=useMemo(()=>s.products.reduce((a,p)=>{const c=calc(p);return {qty:a.qty+n(p.qty),cartons:a.cartons+c.cartons,amount:a.amount+c.amount,free:a.free+n(p.freeAmount),final:a.final+c.final,nw:a.nw+c.tnw,gw:a.gw+c.tgw,cbm:a.cbm+c.totalCbm}},{qty:0,cartons:0,amount:0,free:0,final:0,nw:0,gw:0,cbm:0}),[s.products]);
 const packingItems=s.packingProducts?.length?s.packingProducts:s.products,packingTotals=useMemo(()=>packingItems.reduce((a,p)=>{const c=calc(p);return {qty:a.qty+n(p.qty),cartons:a.cartons+c.cartons,amount:0,free:0,final:0,nw:a.nw+c.tnw,gw:a.gw+c.tgw,cbm:a.cbm+c.totalCbm}},{qty:0,cartons:0,amount:0,free:0,final:0,nw:0,gw:0,cbm:0}),[packingItems]);
 const issues=useMemo(()=>[{ok:!!s.basic.invoiceNo,text:"发票编号 / Invoice No.",step:0},{ok:!!s.buyer.name,text:"客户名称 / Buyer",step:1},{ok:s.products.length>0&&s.products.every(p=>p.qty>0&&p.price>=0),text:"产品数量与单价",step:2},{ok:s.products.every(p=>Math.abs(calc(p).amount-p.qty*p.price)<.01),text:"产品金额计算",step:2},{ok:s.products.every(p=>p.nw<=p.gw),text:"净重不大于毛重",step:2},{ok:!!s.basic.currency&&!!s.basic.incoterm,text:"币种与贸易条款",step:0},{ok:!!s.basic.shipDate,text:"预计出货日期",step:0},{ok:s.products.every(p=>!!p.declaration),text:"报关要素（待人工确认）",step:5},{ok:!!s.certificate.type&&!!s.certificate.originCriterion,text:"原产地申请资料",step:5}], [s]);
 const save=()=>{const item={...s,updatedAt:new Date().toISOString()};const next=[item,...history.filter(x=>x.id!==s.id)];setHistory(next);localStorage.setItem("acpkg.shipping.history",JSON.stringify(next));localStorage.setItem("acpkg.shipping.draft",JSON.stringify(item));say("草稿与历史记录已保存")};
 const fileBase=(type=doc)=>`${type.replaceAll(" ","_")}_${(s.buyer.name||"Customer").replace(/[^a-zA-Z0-9]+/g,"_")}_${s.basic.invoiceNo||"DRAFT"}_${s.basic.invoiceDate||today()}`;
 const workbook=async(type=doc)=>{try{const filename=type==="Commercial Invoice"?`${fileBase(type).replace("Commercial_Invoice","Customer_Clearance_Files")}.xlsx`:`${fileBase(type)}.xlsx`;const res=await fetch("/api/shipping-docs/export",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({shipment:s,type,includeStamp})});if(!res.ok)throw new Error("export");const url=URL.createObjectURL(await res.blob()),link=document.createElement("a");link.href=url;link.download=filename;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);say(type==="Customs Declaration Data"?"中国出口报关资料已导出":"文件已单独导出")}catch{say("模板导出失败，请重试")}};
 const backupPayload=()=>({version:1,shipment:s,history});
 const exportBackupExcel=()=>{const wb=XLSX.utils.book_new(),pairs=(title:string,x:Record<string,unknown>)=>XLSX.utils.aoa_to_sheet([[title,"Value"],...Object.entries(x).map(([k,v])=>[k,typeof v==="boolean"?(v?"是":"否"):v])]);XLSX.utils.book_append_sheet(wb,pairs("基础信息",s.basic),"基础信息");XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet([{role:"卖方",...s.seller},{role:"买方",...s.buyer},{role:"收货人",...s.consignee},{role:"通知方",...s.notify}]),"买卖双方");XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(s.products),"产品明细");XLSX.utils.book_append_sheet(wb,pairs("运输与订舱",s.transport),"运输与订舱");XLSX.utils.book_append_sheet(wb,pairs("原产地证",s.certificate),"原产地证");const raw=JSON.stringify(backupPayload()),chunks=raw.match(/[\s\S]{1,30000}/g)||[raw];XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet([["ACPKG_BACKUP_V1"],...chunks.map(x=>[x])]),"__BACKUP_DATA__");wb.Workbook={Sheets:wb.SheetNames.map((name,i)=>({name,Hidden:i===wb.SheetNames.length-1?1:0}))};const bytes=XLSX.write(wb,{type:"array",bookType:"xlsx"});downloadBlob(new Blob([bytes],{type:"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"}),`ACPKG_完整备份_${today()}.xlsx`);setBackupOpen(false);say("Excel 完整备份已导出")};
 const exportBackupWord=()=>{const kv=(title:string,x:Record<string,unknown>)=>`<h2>${safe(title)}</h2><table>${Object.entries(x).map(([k,v])=>`<tr><th>${safe(k)}</th><td>${safe(v)}</td></tr>`).join("")}</table>`,party=(title:string,p:Party)=>kv(title,p),productRows=s.products.map((p,i)=>`<tr><td>${i+1}</td><td>${safe(p.customerItem)}</td><td>${safe(p.model)}</td><td>${safe(p.en)}</td><td>${safe(p.zh)}</td><td>${safe(p.hs)}</td><td>${p.qty} ${safe(p.unit)}</td><td>${p.price}</td><td>${calc(p).cartons}</td><td>${calc(p).tgw}</td><td>${calc(p).totalCbm}</td></tr>`).join("");const html=`<!doctype html><html><head><meta charset="utf-8"><style>@page{size:A4;margin:18mm}body{font-family:Arial,'Microsoft YaHei',sans-serif;color:#17233c;font-size:10pt}h1{color:#0e2e59;border-bottom:2px solid #20a36a;padding-bottom:8px}h2{color:#173f75;margin-top:22px}table{width:100%;border-collapse:collapse;margin:8px 0 14px}th,td{border:1px solid #c8d2df;padding:6px;vertical-align:top}th{background:#eaf1f8;text-align:left}p{white-space:pre-wrap}</style></head><body><h1>AC PKG 外贸出货资料备份</h1><p>备份日期：${today()}<br>出货项目：${safe(s.basic.shipment)}<br>发票号：${safe(s.basic.invoiceNo)}</p>${kv("基础信息",s.basic)}${party("卖方",s.seller)}${party("买方",s.buyer)}${party("收货人",s.consignee)}${party("通知方",s.notify)}<h2>产品明细</h2><table><tr><th>#</th><th>Customer Item</th><th>Model</th><th>English</th><th>中文品名</th><th>HS Code</th><th>数量</th><th>单价</th><th>箱数</th><th>毛重</th><th>CBM</th></tr>${productRows}</table>${kv("运输与订舱",s.transport)}${kv("原产地证",s.certificate)}<h2>合同条款</h2><p>${safe(s.contract)}</p></body></html>`;downloadBlob(new Blob(["\ufeff",html],{type:"application/msword"}),`ACPKG_资料备份_${today()}.doc`);setBackupOpen(false);say("Word 资料备份已导出")};
 const importBackup=(f:File)=>{const apply=(x:any)=>{if(x.version!==1||!x.shipment)throw 0;setS(x.shipment);setHistory(x.history||[]);say("备份恢复成功")};const r=new FileReader();r.onload=()=>{try{if(f.name.toLowerCase().endsWith(".xlsx")){const wb=XLSX.read(r.result,{type:"array"}),ws=wb.Sheets["__BACKUP_DATA__"];if(!ws)throw 0;const rows=XLSX.utils.sheet_to_json<unknown[]>(ws,{header:1});apply(JSON.parse(rows.slice(1).map(x=>String(x[0]||"")).join("")))}else apply(JSON.parse(String(r.result)))}catch{say("备份文件无效")}};f.name.toLowerCase().endsWith(".xlsx")?r.readAsArrayBuffer(f):r.readAsText(f)};
 const importProducts=(f:File)=>{const r=new FileReader();r.onload=()=>{try{const wb=XLSX.read(r.result),data=XLSX.utils.sheet_to_json<Record<string,unknown>>(wb.Sheets[wb.SheetNames[0]]);const ps=data.map(x=>product({customerItem:String(x["Customer Item No."]||""),model:String(x["Supplier Model"]||""),en:String(x["English Description"]||""),zh:String(x["Chinese Description"]||""),hs:String(x["HS Code"]||""),qty:n(x.Quantity),unit:String(x.Unit||"PCS"),price:n(x["Unit Price"]),pcsCtn:n(x["PCS/CTN"])||1,nw:n(x["N.W./CTN"]),gw:n(x["G.W./CTN"]),l:n(x.Length),w:n(x.Width),h:n(x.Height),declaration:String(x["Declaration Elements"]||"")}));if(ps.length)update(z=>({...z,products:ps}));say(`已导入 ${ps.length} 个产品`)}catch{say("Excel 格式无法识别")}};r.readAsArrayBuffer(f)};
 const importSource=(f:File,kind:"pi"|"packing")=>{const r=new FileReader();r.onload=()=>{try{const parsed=readSourceWorkbook(r.result as ArrayBuffer,kind);if(!parsed.products.length&&!Object.keys(parsed.basic).length)throw 0;update(z=>{if(kind==="packing")return {...z,packingProducts:parsed.products.map(p=>product({...p,id:crypto.randomUUID()}))};const current=z.products.filter(p=>p.en||p.zh||p.model),merged=parsed.products.map((incoming,i)=>{const found=current.find(p=>(incoming.model&&p.model===incoming.model)||(incoming.en&&key(p.en)===key(incoming.en)))||current[i];return product({...found,...incoming,id:found?.id||crypto.randomUUID(),declaration:found?.declaration||"待人工确认"})});return {...z,basic:{...z.basic,...Object.fromEntries(Object.entries(parsed.basic).filter(([,v])=>v))},buyer:{...z.buyer,...Object.fromEntries(Object.entries(parsed.buyer).filter(([,v])=>v))},consignee:z.consignee.name?z.consignee:{...z.consignee,...parsed.buyer},products:merged.length?merged:z.products}});setSourceFiles(x=>({...x,[kind]:f.name}));setStep(6);say(kind==="pi"?`PI 已识别：${parsed.products.length} 项产品`:`装箱清单已识别：${parsed.products.length} 类包装明细，PI 产品未被覆盖`)}catch{say("未识别到有效表格，请上传 PI 或装箱清单 Excel")}};r.readAsArrayBuffer(f)};
 const template=()=>{const ws=XLSX.utils.aoa_to_sheet([["Customer Item No.","Supplier Model","English Description","Chinese Description","HS Code","Quantity","Unit","Unit Price","PCS/CTN","N.W./CTN","G.W./CTN","Length","Width","Height","Declaration Elements"],["ITEM-001","AC-001","Cosmetic Jar","化妆品罐","3923300000",1000,"PCS",1.2,100,8,9,48,38,32,"待人工确认"]]);const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,"Products");XLSX.writeFile(wb,"ACPKG_Product_Import_Template.xlsx")};
 const newDoc=()=>setConfirm({text:"新建出货单会替换当前草稿，确定继续？",go:()=>{setS(blank());setStep(0);setConfirm(null);say("已新建出货单")}});
 const exportPrint=()=>{setPreview(true);if(issues.some(x=>!x.ok))say("当前按草稿输出，缺失资料保留为空");setTimeout(()=>window.print(),250)};
 const steps=["基础信息","买卖双方","产品明细","装箱明细","运输及订舱","报关与原产地证","文件生成","历史记录"];
 return <div className="shipping-app">
  <header className="topbar"><div className="brand"><div className="logo">AC <b>PKG</b></div><div><strong>外贸出货文件助手</strong><small>Export Shipping Document Assistant</small></div></div><div className="top-actions"><button onClick={()=>setLang(lang==="zh"?"en":"zh")}><Languages/> {lang==="zh"?"EN":"中文"}</button><button onClick={()=>{setS(demo());setStep(0);say("演示数据已载入")}}><Ship/> 演示数据</button><button onClick={newDoc}><Plus/> 新建</button><button className="primary" onClick={save}><Save/> 保存草稿</button><button onClick={()=>setStep(7)}><History/> 历史</button><div className="backup-menu"><button onClick={()=>setBackupOpen(x=>!x)}><Download/> 备份</button>{backupOpen&&<div className="backup-options"><button onClick={exportBackupExcel}><FileSpreadsheet/> Excel 完整备份</button><button onClick={exportBackupWord}><FileText/> Word 资料备份</button></div>}</div><button onClick={()=>importRef.current?.click()}><Upload/> 恢复</button><input hidden ref={importRef} type="file" accept=".xlsx,.json" onChange={e=>e.target.files?.[0]&&importBackup(e.target.files[0])}/></div></header>
  <nav className="steps">{steps.map((x,i)=><button key={x} className={step===i?"active":""} onClick={()=>setStep(i)}><span>{i+1}</span>{x}</button>)}</nav>
  <main>
   <div className="page-title"><div><p>{s.demo?"演示数据 · DEMO DATA":"当前草稿"}</p><h1>{steps[step]}</h1></div><div className="autosave"><Check/> 自动保存已开启</div></div>
   <section className="card source-import"><div className="section-head"><div><h2>上传 PI 与装箱清单，生成客户清关资料</h2><p>当前阶段只处理清关资料：商业发票 Commercial Invoice 与装箱清单 Packing List，版式采用公司 2026 固定模板。</p></div><div className="source-status"><span className={sourceFiles.pi?"ready":""}>{sourceFiles.pi?`✓ PI：${sourceFiles.pi}`:"PI 未上传"}</span><span className={sourceFiles.packing?"ready":""}>{sourceFiles.packing?`✓ 装箱单：${sourceFiles.packing}`:"装箱单未上传"}</span></div></div><div className="source-buttons"><button className="primary" onClick={()=>piRef.current?.click()}><Upload/> 上传 PI</button><button onClick={()=>packingRef.current?.click()}><Upload/> 上传装箱清单</button><button onClick={()=>{setDoc("Commercial Invoice");setStep(6)}}><FileText/> 查看清关资料</button><input hidden ref={piRef} type="file" accept=".xlsx,.xls" onChange={e=>e.target.files?.[0]&&importSource(e.target.files[0],"pi")}/><input hidden ref={packingRef} type="file" accept=".xlsx,.xls" onChange={e=>e.target.files?.[0]&&importSource(e.target.files[0],"packing")}/></div><small>导出“整套客户清关资料”时，一个 Excel 文件内包含 Invoice 和 Packing list 两张工作表。</small></section>
   {step===0&&<section className="card"><div className="section-head"><h2>订单基础资料</h2><button onClick={()=>{const no=`AC-${today().replaceAll("-","")}-001`;update(z=>({...z,basic:{...z.basic,orderNo:no,invoiceNo:no,packingNo:no,piNo:no,contractNo:no}}));say("编号已生成")}}><RefreshCw/> 自动生成编号</button></div><div className="form-grid">{Object.entries(labels).map(([k,l])=><Field key={k} label={lang==="zh"?`${l[0]} · ${l[1]}`:l[1]} value={s.basic[k]} type={k.toLowerCase().includes("date")?"date":"text"} onChange={v=>update(z=>({...z,basic:{...z.basic,[k]:v}}))}/>)}</div></section>}
   {step===1&&<div className="stack"><section className="card"><h2>卖方 Seller <em>默认资料，可编辑</em></h2><div className="form-grid"><Field label="中文公司名" value={s.seller.cn} onChange={v=>update(z=>({...z,seller:{...z.seller,cn:v}}))}/>{(["name","address","contact","phone","email","tax","bank","bankAddress","account","accountNo","swift"] as const).map(k=><Field key={k} label={k} value={s.seller[k]} onChange={v=>update(z=>({...z,seller:{...z.seller,[k]:v}}))}/>)}</div></section><PartyForm title="买方 Buyer" p={s.buyer} set={p=>update(z=>({...z,buyer:p}))}/><div className="sync-row"><button onClick={()=>update(z=>({...z,consignee:{...z.buyer}}))}><Copy/> 与买方相同</button></div><PartyForm title="收货人 Consignee" p={s.consignee} set={p=>update(z=>({...z,consignee:p}))}/><div className="sync-row"><button onClick={()=>update(z=>({...z,notify:{...z.consignee}}))}><Copy/> 与收货人相同</button></div><PartyForm title="通知方 Notify Party" p={s.notify} set={p=>update(z=>({...z,notify:p}))}/></div>}
   {step===2&&<Products s={s} update={update} importRef={productRef} importProducts={importProducts} template={template} workbook={()=>workbook("Commercial Invoice")} say={say}/>} 
   {step===3&&<section className="card"><div className="section-head"><div><h2>装箱明细 Packing Details</h2><p>{s.packingProducts?.length?"来自上传的装箱清单；同品名的多种装箱规格已汇总":"尚未上传装箱清单，暂用 PI 产品显示"}</p></div></div><Summary t={packingTotals} currency={s.basic.currency}/><div className="table-wrap"><table><thead><tr><th>Product</th><th>Quantity</th><th>Cartons</th><th>PCS/CTN</th><th>Carton Size (cm)</th><th>Total N.W.</th><th>Total G.W.</th><th>Total CBM</th><th>Shipping Mark</th></tr></thead><tbody>{packingItems.map(p=>{const c=calc(p);return <tr key={p.id}><td>{p.en||"—"}</td><td>{p.qty}</td><td>{c.cartons}</td><td>{p.pcsCtn||"—"}</td><td>{p.l}×{p.w}×{p.h}</td><td>{round(c.tnw)}</td><td>{round(c.tgw)}</td><td>{round(c.totalCbm,4)}</td><td>{p.mark}</td></tr>})}</tbody></table></div></section>}
   {step===4&&<Transport s={s} update={update}/>} 
   {step===5&&<Compliance s={s} update={update} say={say}/>} 
   {step===6&&<Documents s={s} doc={doc} setDoc={setDoc} totals={totals} issues={issues} setStep={setStep} preview={()=>setPreview(true)} print={exportPrint} excel={()=>workbook()} includeStamp={includeStamp} setIncludeStamp={setIncludeStamp}/>}
   {step===7&&<HistoryPanel items={history} query={query} setQuery={setQuery} load={(x:Shipment)=>{setS(x);setStep(0);say("历史出货单已载入")}} copy={(x:Shipment)=>{setS({...x,id:crypto.randomUUID(),createdAt:new Date().toISOString(),basic:{...x.basic,invoiceNo:"",orderNo:""}});setStep(0);say("已复制为新出货单")}} remove={(x:Shipment)=>setConfirm({text:`确定删除 ${x.basic.invoiceNo||x.basic.orderNo}？此操作不可撤销。`,go:()=>{const h=history.filter(i=>i.id!==x.id);setHistory(h);localStorage.setItem("acpkg.shipping.history",JSON.stringify(h));setConfirm(null);say("记录已删除")}})}/>} 
   <div className="pager"><button disabled={step===0} onClick={()=>setStep(x=>x-1)}><ChevronLeft/> 上一步</button><button className="primary" disabled={step===7} onClick={()=>setStep(x=>x+1)}>下一步 <ChevronRight/></button></div>
  </main>
  {preview&&<div className="modal preview-modal"><div className="modal-bar no-print"><b>{docLabel(doc)} 预览</b><div><button onClick={()=>workbook()}><FileSpreadsheet/> Excel</button><button onClick={exportPrint}><Printer/> 打印 / PDF</button><button onClick={()=>setPreview(false)}><X/></button></div></div><div className={`paper-wrap${doc==="Customs Declaration Data"?" customs-paper-wrap":doc==="Certificate of Origin Data"?" certificate-paper-wrap":["Booking Note","Forwarder Handover Sheet"].includes(doc)?" booking-paper-wrap":""}`}>{["Packing List","Proforma Invoice","Sales Contract"].includes(doc)&&<div className="customs-material-tag">报关资料</div>}{doc==="Customs Declaration Data"?<CustomsDocumentView s={s} totals={totals}/>:doc==="Certificate of Origin Data"?<CertificateDocumentView s={s}/>:(["Booking Note","Forwarder Handover Sheet"].includes(doc)?<BookingDocumentView s={s} totals={totals}/>:<DocumentView s={s} type={doc} totals={totals}/>)} {includeStamp&&<img className="preview-stamp" src="/ac-pkg-stamp.png" alt="公司章"/>}</div></div>}
  {confirm&&<div className="modal confirm"><div className="confirm-box"><CircleAlert/><h3>请确认</h3><p>{confirm.text}</p><div><button onClick={()=>setConfirm(null)}>取消</button><button className="danger" onClick={confirm.go}>确认</button></div></div></div>}
  {toast&&<div className="toast"><Check/>{toast}</div>}
 </div>
}

function Summary({t,currency}:{t:{qty:number;cartons:number;amount:number;free:number;final:number;nw:number;gw:number;cbm:number};currency:string}){const x=t;return <div className="summary">{[["Total Quantity",x.qty],["Total Cartons",x.cartons],["Product Amount",`${currency} ${money(x.amount)}`],["Free Amount",`${currency} ${money(x.free)}`],["Final Payable",`${currency} ${money(x.final)}`],["Net Weight",`${round(x.nw)} KG`],["Gross Weight",`${round(x.gw)} KG`],["Total CBM",round(x.cbm,4)]].map(a=><div key={a[0]}><small>{a[0]}</small><strong>{a[1]}</strong></div>)}</div>}
function Products({s,update,importRef,importProducts,template,workbook,say}:any){const set=(id:string,k:string,v:any)=>update((z:Shipment)=>({...z,products:z.products.map(p=>p.id===id?{...p,[k]:v}:p)}));return <section className="card"><div className="section-head"><div><h2>产品明细 Products</h2><p>金额、箱数、重量和体积自动计算</p></div><div className="button-row"><button onClick={()=>update((z:Shipment)=>({...z,products:[...z.products,product()]}))}><Plus/> 添加</button><button onClick={()=>importRef.current?.click()}><Upload/> 导入 Excel</button><button onClick={template}><Download/> 下载模板</button><button onClick={workbook}><FileSpreadsheet/> 导出</button><input hidden ref={importRef} type="file" accept=".xlsx,.xls" onChange={(e:any)=>e.target.files?.[0]&&importProducts(e.target.files[0])}/></div></div><div className="table-wrap products"><table><thead><tr>{["","No.","Customer Item","Model","English Description","中文品名","HS Code","Material","Qty","Unit","Unit Price","Amount","Free Amount","Discount","Final","PCS/CTN","Cartons","N.W./CTN","G.W./CTN","L","W","H","Total CBM","Declaration Elements","Mark","Action"].map(x=><th key={x}>{x}</th>)}</tr></thead><tbody>{s.products.map((p:Product,i:number)=>{const c=calc(p);const inp=(k:keyof Product,type="text")=><input type={type} value={String(p[k]??"")} onChange={e=>set(p.id,k,type==="number"?n(e.target.value):e.target.value)}/>;return <tr key={p.id}><td><input type="checkbox" checked={!!p.selected} onChange={e=>set(p.id,"selected",e.target.checked)}/></td><td>{i+1}</td><td>{inp("customerItem")}</td><td>{inp("model")}</td><td>{inp("en")}</td><td>{inp("zh")}</td><td>{inp("hs")}</td><td>{inp("material")}</td><td>{inp("qty","number")}</td><td><select value={p.unit} onChange={e=>set(p.id,"unit",e.target.value)}>{["PCS","SETS","KG","CTNS"].map(x=><option key={x}>{x}</option>)}</select></td><td>{inp("price","number")}</td><td className="computed">{money(c.amount)}</td><td>{inp("freeAmount","number")}</td><td>{inp("discount","number")}</td><td className="computed">{money(c.final)}</td><td>{inp("pcsCtn","number")}</td><td className="computed">{c.cartons}</td><td>{inp("nw","number")}</td><td>{inp("gw","number")}</td><td>{inp("l","number")}</td><td>{inp("w","number")}</td><td>{inp("h","number")}</td><td className="computed">{c.totalCbm}</td><td>{inp("declaration")}</td><td>{inp("mark")}</td><td><div className="row-actions"><button title="复制" onClick={()=>update((z:Shipment)=>({...z,products:[...z.products,product({...p,id:crypto.randomUUID()})]}))}><Copy/></button><button title="删除" disabled={s.products.length===1} onClick={()=>update((z:Shipment)=>({...z,products:z.products.filter(x=>x.id!==p.id)}))}><Trash2/></button></div></td></tr>})}</tbody></table></div><div className="batch"><button onClick={()=>{const count=s.products.filter((p:Product)=>p.selected).length;if(!count)return say("请先勾选产品");update((z:Shipment)=>({...z,products:z.products.filter(p=>!p.selected)}));say(`已删除 ${count} 行`)}}><Trash2/> 批量删除</button></div></section>}
function Transport({s,update}:any){const fields=[["mode","运输方式"],["type","运输类型"],["loading","起运港"],["discharge","目的港"],["destination","最终目的地"],["line","船公司"],["vessel","船名"],["voyage","航次"],["etd","ETD"],["eta","ETA"],["forwarder","货代公司"],["forwarderContact","货代联系人"],["forwarderEmail","货代邮箱"],["forwarderPhone","货代电话"],["booking","订舱号"],["bl","提单号"],["container","集装箱号"],["seal","封条号"],["containerType","柜型"],["containerQty","柜量"],["commodity","货物名称"],["customsMode","报关方式"],["broker","报关行"],["brokerContact","报关联系人"],["customsCutoff","报关截止"],["vgmCutoff","VGM 截止"],["siCutoff","SI 截止"],["warehouse","进仓地址"],["warehouseNo","进仓编号"],["special","特殊运输要求"],["remarks","运输备注"]];return <section className="card"><h2>运输及订舱 Shipping</h2><datalist id="ports">{["Guangzhou","Huangpu","Nansha","Shenzhen","Yantian","Shekou"].map(x=><option key={x}>{x}</option>)}</datalist><div className="form-grid">{fields.map(([k,l])=><Field key={k} label={l} list={k==="loading"?"ports":undefined} type={["etd","eta"].includes(k)?"date":["customsCutoff","vgmCutoff","siCutoff"].includes(k)?"datetime-local":"text"} value={String(s.transport[k]||"")} onChange={v=>update((z:Shipment)=>({...z,transport:{...z.transport,[k]:v}}))}/>)}</div><div className="checks">{[["dangerous","危险品"],["battery","带电"],["wood","木质包装"],["fumigation","需要熏蒸"]].map(([k,l])=><label key={k}><input type="checkbox" checked={!!s.transport[k]} onChange={e=>update((z:Shipment)=>({...z,transport:{...z.transport,[k]:e.target.checked}}))}/>{l}</label>)}</div></section>}
function Compliance({s,update,say}:any){return <div className="stack"><section className="card"><div className="section-head"><div><h2>报关资料 Customs Data</h2><p>不能自动判断的字段保留“待人工确认”</p></div><button onClick={()=>{update((z:Shipment)=>({...z,products:z.products.map(p=>({...p,declaration:p.declaration||"待人工确认"}))}));say("已从产品明细同步")}}><RefreshCw/> 从产品明细同步</button></div><div className="table-wrap"><table><thead><tr><th>中文品名</th><th>English Name</th><th>HS Code</th><th>Brand</th><th>Model</th><th>Material</th><th>Usage</th><th>Origin</th><th>Quantity</th><th>Total Value</th><th>Declaration Elements</th></tr></thead><tbody>{s.products.map((p:Product)=><tr key={p.id}><td>{p.zh||"待人工确认"}</td><td>{p.en||"Pending"}</td><td>{p.hs||"待人工确认"}</td><td>{p.brand||"待人工确认"}</td><td>{p.model}</td><td>{p.material||"待人工确认"}</td><td>{p.usage||"待人工确认"}</td><td>{p.origin}</td><td>{p.qty} {p.unit}</td><td>{money(calc(p).final)}</td><td className={!p.declaration?"pending":""}>{p.declaration||"待人工确认"}</td></tr>)}</tbody></table></div></section><section className="card"><div className="section-head"><div><h2>原产地证申请资料</h2><p>Certificate of Origin Application Data — 非正式签发证书</p></div><button onClick={()=>{update((z:Shipment)=>({...z,certificate:{...z.certificate,manufacturer:z.seller.name,date:z.basic.invoiceDate}}));say("已同步发票及装箱资料")}}><RefreshCw/> 同步资料</button></div><div className="form-grid">{[["type","Certificate Type"],["originCriterion","Origin Criterion"],["manufacturer","Manufacturer"],["place","Declaration Place"],["date","Declaration Date"],["signatory","Authorized Signatory"],["remarks","Special Remarks"]].map(([k,l])=><Field key={k} label={l} value={s.certificate[k]||""} onChange={v=>update((z:Shipment)=>({...z,certificate:{...z.certificate,[k]:v}}))}/>)}</div></section><section className="card"><h2>销售合同条款 Contract Terms</h2><textarea className="contract" value={s.contract} onChange={e=>update((z:Shipment)=>({...z,contract:e.target.value}))}/></section></div>}
function Documents({s,doc,setDoc,totals,issues,setStep,preview,print,excel,includeStamp,setIncludeStamp}:any){return <div className="doc-grid"><section className="card"><h2>清关资料检查</h2><div className="issues">{issues.slice(0,7).map((x:any,i:number)=><button key={i} onClick={()=>setStep(x.step)} className={x.ok?"ok":"bad"}>{x.ok?<Check/>:<CircleAlert/>}<span>{x.text}</span><b>{x.ok?"已完成":"待填写"}</b></button>)}</div><p className="draft-note">资料不完整也可以保存、预览、打印和下载，缺失内容将保留为空。</p></section><section className="card"><div className="section-head"><div><h2>客户清关文件生成</h2><p>按照公司“报关&amp;清关-2026版本”固定模板生成，仅处理商业发票和装箱清单。</p></div><label className="stamp-toggle"><input type="checkbox" checked={includeStamp} onChange={e=>setIncludeStamp(e.target.checked)}/><img src="/ac-pkg-stamp.png" alt="公司章"/><span>添加公司章</span></label></div><div className="doc-list">{DOCS.map((x:string)=><button className={doc===x?"selected":""} key={x} onClick={()=>setDoc(x as DocType)}><FileText/><span>{docLabel(x)}<small>{x==="Commercial Invoice"?"包含 Invoice + Packing list 两张表":"仅导出 Packing list"}</small></span><ChevronRight/></button>)}</div><div className="generate"><button onClick={preview}><FileText/> 网页预览</button><button onClick={print}><Printer/> 打印 / 导出 PDF</button><button className="primary" onClick={excel}><FileSpreadsheet/> 下载 Excel</button></div></section></div>}
function HistoryPanel({items,query,setQuery,load,copy,remove}:any){const list=items.filter((x:Shipment)=>[x.basic.orderNo,x.basic.invoiceNo,x.buyer.name].join(" ").toLowerCase().includes(query.toLowerCase()));return <section className="card"><div className="section-head"><div><h2>历史出货单</h2><p>保存于当前浏览器，本机离线可用</p></div><label className="search"><Search/><input placeholder="订单号 / 客户 / 发票号" value={query} onChange={e=>setQuery(e.target.value)}/></label></div><div className="history-list">{list.length?list.map((x:Shipment)=><article key={x.id}><div><b>{x.basic.shipment||"未命名出货单"}</b><span>{x.buyer.name||"未填写客户"} · {x.basic.invoiceNo||"无发票号"}</span><small>创建 {new Date(x.createdAt).toLocaleString()} · 更新 {new Date(x.updatedAt).toLocaleString()}</small></div><div><button onClick={()=>load(x)}>编辑</button><button onClick={()=>copy(x)}><Copy/> 复制</button><button onClick={()=>remove(x)}><Trash2/> 删除</button></div></article>):<div className="empty"><Archive/><b>暂无历史记录</b><span>保存当前草稿后会显示在这里</span></div>}</div></section>}
function DocumentView({s,type,totals}:any){const commercial=["Commercial Invoice","Proforma Invoice","Sales Contract"].includes(type);return <article className="paper"><header><div className="paper-logo">AC <b>PKG</b></div><div><b>{s.seller.name}</b><span>{s.seller.address}</span><span>{s.seller.phone} · {s.seller.email}</span></div></header><h1>{type.toUpperCase()}</h1>{type==="Certificate of Origin Data"&&<div className="notice">APPLICATION DATA ONLY — NOT AN OFFICIAL CERTIFICATE / 仅供申请资料使用，非正式签发证书</div>}<div className="paper-meta"><div><b>Seller / Shipper</b><span>{s.seller.name}</span><span>{s.seller.address}</span></div><div><b>Buyer / Consignee</b><span>{s.buyer.name}</span><span>{s.buyer.address}, {s.buyer.country}</span></div><div><b>Invoice No.</b><span>{s.basic.invoiceNo}</span><b>Date</b><span>{s.basic.invoiceDate}</span></div><div><b>PO / Contract</b><span>{s.basic.poNo} / {s.basic.contractNo}</span><b>Terms</b><span>{s.basic.incoterm} · {s.basic.payment}</span></div></div>{type==="Booking Note"&&<div className="paper-meta"><div><b>Notify Party</b><span>{s.notify.name}<br/>{s.notify.address}</span></div><div><b>Route</b><span>{String(s.transport.loading)} → {String(s.transport.discharge)} → {String(s.transport.destination)}</span></div><div><b>Booking / Container</b><span>{String(s.transport.booking)} / {String(s.transport.containerType)}</span></div><div><b>ETD / Special Instructions</b><span>{String(s.transport.etd)} / {String(s.transport.special)}</span></div></div>}<table><thead><tr><th>No.</th><th>Description / 产品</th><th>HS Code</th><th>Qty</th>{commercial?<><th>Unit Price</th><th>Amount</th></>:<><th>Cartons</th><th>N.W.</th><th>G.W.</th><th>CBM</th></>}</tr></thead><tbody>{s.products.map((p:Product,i:number)=>{const c=calc(p);return <tr key={p.id}><td>{i+1}</td><td><b>{p.en}</b><br/>{p.zh}<br/><small>{type==="Customs Declaration Data"?p.declaration:p.model}</small></td><td>{p.hs}</td><td>{p.qty} {p.unit}</td>{commercial?<><td>{money(p.price)}</td><td>{money(c.final)}</td></>:<><td>{c.cartons}</td><td>{c.tnw}</td><td>{c.tgw}</td><td>{c.totalCbm}</td></>}</tr>})}</tbody><tfoot><tr><td colSpan={3}>TOTAL</td><td>{totals.qty}</td>{commercial?<><td>{s.basic.currency}</td><td>{money(totals.final)}</td></>:<><td>{totals.cartons}</td><td>{round(totals.nw)}</td><td>{round(totals.gw)}</td><td>{round(totals.cbm,4)}</td></>}</tr></tfoot></table>{type==="Sales Contract"&&<div className="terms"><h3>TERMS AND CONDITIONS</h3><p>{s.contract}</p></div>}{type==="Forwarder Handover Sheet"&&<div className="terms"><h3>HANDOVER DETAILS</h3><p>Forwarder: {String(s.transport.forwarder)} · Booking: {String(s.transport.booking)} · Warehouse: {String(s.transport.warehouse)} · SI Cutoff: {String(s.transport.siCutoff)}</p></div>}<div className="paper-summary"><span>Total Amount: <b>{s.basic.currency} {money(totals.amount)}</b></span><span>Free Amount: <b>{money(totals.free)}</b></span><span>Final Payable: <b>{s.basic.currency} {money(totals.final)}</b></span></div><footer><div>Seller Signature / Stamp<br/><br/><br/>________________________</div><div>{type==="Sales Contract"?"Buyer Signature":"Authorized Signature / Stamp"}<br/><br/><br/>________________________</div></footer><div className="page-no">Page 1</div></article>}
